  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability distance
    edges = []
    for u, v, d in distances:
        mut_dist = max(core_distance[u], core_distance[v], d)
        edges.append((mut_dist, u, v))

    # Sort edges by weight
    edges.sort(key=lambda x: x[0])

    # Union-Find structure
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(node1, node2):
        root1 = find(node1)
        root2 = find(node2)
        if root1 == root2:
            return False
        if rank[root1] < rank[root2]:
            parent[root1] = root2
        elif rank[root1] > rank[root2]:
            parent[root2] = root1
        else:
            parent[root2] = root1
            rank[root1] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
